295			return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
296		}
297	
298		var command string
299		var args []string
300	
301		switch runtime.GOOS {
302		case "darwin":
303			command = "open"
304			args = []string{browserURL}
305		case "linux":
306			command = "xdg-open"
307			args = []string{browserURL}
308		case "windows":
309			command = "cmd"
310			args = []string{"/c", "start", "", browserURL}
311		default:
312			return fmt.Errorf("unsupported platform %s", runtime.GOOS)
313		}
314	
315		cmd := exec.CommandContext(ctx, command, args...)
316		if err := cmd.Start(); err != nil {
317			return fmt.Errorf("start browser command %q: %w", command, err)
318		}
319	
320		if err := cmd.Process.Release(); err != nil {
321			return fmt.Errorf("release browser process: %w", err)
322		}
323	
324		return nil
325	}
