	migratedAgain, err := MigrateLegacyLoginContext()
	if err != nil {
		t.Fatalf("second MigrateLegacyLoginContext: %v", err)
	}
	if migratedAgain {
		t.Fatal("second migration should be a no-op")
	}
}

