package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"

	"github.com/entireio/cli/internal/remotehelper"
)

// EnsureGitRemoteHelper installs a git-remote-entire launcher next to the
// running entire binary so `git clone entire://…` resolves it on PATH.
// Git execs git-remote-entire and the entire CLI dispatches on argv[0]
// (see cmd/entire/remotehelper.go), so the launcher just needs to be the
// entire binary under that name.
//
// On Unix it's a relative symlink to the sibling entire binary, so it
// survives in-place updates that replace that binary. On Windows, where
// symlinks need elevation, it's a copy. Idempotent and safe to call
// repeatedly. Returns the launcher path.
func EnsureGitRemoteHelper() (string, error) {
	exe, err := os.Executable()
	if err != nil {
		return "", fmt.Errorf("resolve executable path: %w", err)
	}
	return ensureGitRemoteHelperFor(exe)
}

// ensureGitRemoteHelperFor is the testable core of EnsureGitRemoteHelper,
// parameterized on the entire binary path.
func ensureGitRemoteHelperFor(exe string) (string, error) {
	dir := filepath.Dir(exe)
	target := filepath.Base(exe) // e.g. "entire" or "entire.exe"
	name := remotehelper.BinaryName
	if runtime.GOOS == "windows" {
		name += ".exe"
	}
	link := filepath.Join(dir, name)

	if runtime.GOOS == "windows" {
		// No symlinks without elevation: copy the binary. argv[0] dispatch
		// keys on the basename (stripping .exe), so a copy works.
		if err := copyExecutable(exe, link); err != nil {
			return "", err
		}
		return link, nil
	}

	// Already a symlink to the right sibling — nothing to do.
	if existing, err := os.Readlink(link); err == nil && existing == target {
		return link, nil
	}
	// Replace whatever is there (stale symlink, or nothing). A relative
	// target keeps the launcher valid after the entire binary is updated
	// in place.
	if err := os.Remove(link); err != nil && !os.IsNotExist(err) {
		return "", fmt.Errorf("remove stale %s: %w", link, err)
	}
	if err := os.Symlink(target, link); err != nil {
		return "", fmt.Errorf("symlink %s -> %s: %w", link, target, err)
	}
	return link, nil
}

// copyExecutable copies src to dst with executable permissions, used on
// Windows where the launcher can't be a symlink.
func copyExecutable(src, dst string) error {
	data, err := os.ReadFile(src) //nolint:gosec // src is the running entire binary
	if err != nil {
		return fmt.Errorf("read %s: %w", src, err)
	}
	if err := os.WriteFile(dst, data, 0o755); err != nil { //nolint:gosec // an executable launcher must be executable
		return fmt.Errorf("write %s: %w", dst, err)
	}
	return nil
}

