package cli

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/entireio/cli/internal/remotehelper"
)

func TestEnsureGitRemoteHelperFor(t *testing.T) {
	t.Parallel()
	if runtime.GOOS == "windows" {
		t.Skip("Unix symlink behavior; Windows uses a copy path")
	}

	dir := t.TempDir()
	exe := filepath.Join(dir, "entire")
	if err := os.WriteFile(exe, []byte("#!/bin/sh\n"), 0o755); err != nil {
		t.Fatalf("seed entire binary: %v", err)
	}

	link := filepath.Join(dir, remotehelper.BinaryName)

	// First run: creates a relative symlink to the sibling binary.
	got, err := ensureGitRemoteHelperFor(exe)
	if err != nil {
		t.Fatalf("ensureGitRemoteHelperFor: %v", err)
	}
	if got != link {
		t.Fatalf("returned path = %q, want %q", got, link)
	}
	target, err := os.Readlink(link)
	if err != nil {
		t.Fatalf("readlink: %v", err)
	}
	if target != "entire" {
		t.Fatalf("symlink target = %q, want relative \"entire\"", target)
	}

	// Idempotent: a second run leaves the correct symlink in place.
	if _, err := ensureGitRemoteHelperFor(exe); err != nil {
		t.Fatalf("second run: %v", err)
	}
	if target, _ := os.Readlink(link); target != "entire" {
		t.Fatalf("after second run, target = %q, want \"entire\"", target)
	}

	// A stale symlink (wrong target) is replaced.
	if err := os.Remove(link); err != nil {
		t.Fatalf("remove: %v", err)
	}
	if err := os.Symlink("something-else", link); err != nil {
		t.Fatalf("seed stale symlink: %v", err)
	}
	if _, err := ensureGitRemoteHelperFor(exe); err != nil {
		t.Fatalf("repair stale: %v", err)
	}
	if target, _ := os.Readlink(link); target != "entire" {
		t.Fatalf("stale symlink not repaired: target = %q", target)
	}
}

