1	package auth
2	
3	import (
4		"errors"
5		"fmt"
6		"net/url"
7		"time"
8	
9		"github.com/entireio/auth-go/tokens"
10		"github.com/entireio/cli/cmd/entire/cli/api"
11		"github.com/entireio/cli/internal/entireclient/contexts"
12		"github.com/entireio/cli/internal/entireclient/tokenstore"
13	)
14	
15	// defaultContextTokenTTL is the encoded keychain expiry used when a login
16	// token carries no usable exp claim (e.g. an opaque, non-JWT bearer). The
17	// server is the real authority on validity; this only governs when local
18	// readers consider the token stale, and we hold no refresh token to act on
19	// it, so a conservative non-zero value is enough to keep the entry usable.
20	const defaultContextTokenTTL = time.Hour
21	
22	// RecordLoginContext records a freshly obtained login token in the
23	// shared contexts.json credential model: it derives the issuer (core
24	// URL), handle, and expiry from the token's own claims, stores the token
25	// in the OS keyring under the entire-core:<issuer> service scheme entiredb
26	// uses, and writes (or updates) the matching context — making it current.
27	//
28	// This is the contexts.json half of login's dual-write: the legacy
29	// entire-cli/<authBaseURL> keyring entry is still written by the caller so
30	// the control-plane readers keep working untouched during the transition.
31	// A login recorded here is visible to entiredb's CLIs (and the in-CLI git
32	// remote helper) because they share this file and keychain layout.
33	//
34	// Returns the context name on success. Errors are returned (not swallowed)
35	// so the caller can warn; login still succeeds on the legacy entry.
36	func RecordLoginContext(rawToken string) (string, error) {
37		claims, err := tokens.ParseClaims(rawToken)
38		if err != nil {
39			return "", fmt.Errorf("parse login token claims: %w", err)
40		}
41		coreURL := claims.Issuer
42		if coreURL == "" {
43			return "", errors.New("login token has no iss claim; cannot derive core URL for a context")
44		}
45		handle := claims.Handle
46		if handle == "" {
47			handle = claims.Subject
48		}
49		if handle == "" {
50			return "", errors.New("login token has no handle/sub claim; cannot key the keychain slot")
51		}
52	
53		keychainService := tokenstore.CoreKeyringService(coreURL)
54	
55		expiresIn := int64(defaultContextTokenTTL.Seconds())
56		if !claims.ExpiresAt.IsZero() {
57			if secs := int64(time.Until(claims.ExpiresAt).Seconds()); secs > 0 {
58				expiresIn = secs
59			}
60		}
61	
62		encoded := tokenstore.EncodeTokenWithExpiration(rawToken, expiresIn)
63		if err := tokenstore.Set(keychainService, handle, encoded); err != nil {
64			return "", fmt.Errorf("store login token in keyring: %w", err)
65		}
66	
67		name := contextNameForCoreURL(coreURL)
68		cfgDir := contexts.DefaultConfigDir()
69		if modErr := contexts.Modify(cfgDir, func(f *contexts.File) (bool, error) {
70			f.Upsert(&contexts.Context{
71				Name:            name,
72				CoreURL:         coreURL,
73				Handle:          handle,
74				KeychainService: keychainService,
75			})
76			// The just-completed login becomes the active context (kubectl
77			// use-context semantics). Upsert only sets current when empty, so
78			// set it explicitly to cover re-login into an existing context.
79			f.CurrentContext = name
80			return true, nil
81		}); modErr != nil {
82			return "", fmt.Errorf("write context %q: %w", name, modErr)
83		}
84	
85		return name, nil
86	}
87	
88	// MigrateLegacyLoginContext bridges users who logged in before the
89	// contexts.json dual-write existed: if the legacy entire-cli/<authBaseURL>
90	// keyring entry holds a usable JWT and no context yet covers its issuer,
91	// it records an equivalent context (and keychain entry under the shared
92	// scheme) so the git remote helper can authenticate without a re-login.
93	//
94	// Returns (true, nil) when it created a context. No-ops — returning
95	// (false, nil) — when there's no legacy token, the token is opaque
96	// (no derivable issuer), or a context for that issuer already exists.
97	// Idempotent: safe to call on every helper invocation.
98	func MigrateLegacyLoginContext() (migrated bool, err error) {
99		legacy, err := NewStore().GetToken(api.AuthBaseURL())
100		if err != nil {
101			return false, fmt.Errorf("read legacy login token: %w", err)
102		}
103		if legacy == "" {
104			return false, nil
105		}
106		claims, parseErr := tokens.ParseClaims(legacy)
107		if parseErr != nil || claims.Issuer == "" {
108			// Opaque/unsigned legacy token — can't derive a context from it.
109			return false, nil //nolint:nilerr // absence of a JWT issuer is not an error here
