16	// makeJWT builds a three-segment JWT-shaped string with a non-"none" alg
17	// (so ParseClaims accepts it) and the given payload. The signature segment
18	// is arbitrary — claims are parsed unverified.
19	func makeJWT(t *testing.T, payloadJSON string) string {
20		t.Helper()
21		enc := base64.RawURLEncoding
22		header := enc.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
23		payload := enc.EncodeToString([]byte(payloadJSON))
24		return header + "." + payload + "." + enc.EncodeToString([]byte("sig"))
25	}
