27	func TestRecordLoginContext_WritesContextAndToken(t *testing.T) {
28		// Sets ENTIRE_CONFIG_DIR and swaps the keyring backend — process-global
29		// state, so this test cannot run in parallel.
30		cfgDir := t.TempDir()
31		t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
32		restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
33		t.Cleanup(restore)
34	
35		const coreURL = "https://core.example.com"
36		const handle = "alice"
37		exp := time.Now().Add(2 * time.Hour).Unix()
38		token := makeJWT(t, fmt.Sprintf(`{"iss":%q,"handle":%q,"exp":%d}`, coreURL, handle, exp))
39	
40		name, err := RecordLoginContext(token)
41		if err != nil {
42			t.Fatalf("RecordLoginContext: %v", err)
43		}
44		if name != "core.example.com" {
45			t.Fatalf("context name = %q, want core.example.com", name)
46		}
47	
48		// Context recorded and made current.
49		f, err := contexts.Load(cfgDir)
50		if err != nil {
51			t.Fatalf("load contexts: %v", err)
52		}
53		if f.CurrentContext != name {
54			t.Fatalf("current_context = %q, want %q", f.CurrentContext, name)
55		}
56		c := f.Find(name)
57		if c == nil {
58			t.Fatalf("context %q not found", name)
59		}
60		if c.CoreURL != coreURL || c.Handle != handle {
61			t.Fatalf("context = {CoreURL:%q Handle:%q}, want {%q %q}", c.CoreURL, c.Handle, coreURL, handle)
62		}
63		wantService := tokenstore.CoreKeyringService(coreURL)
64		if c.KeychainService != wantService {
65			t.Fatalf("KeychainService = %q, want %q", c.KeychainService, wantService)
66		}
67	
68		// Token stored at the context's keychain slot, decodable with a
69		// future expiry.
70		encoded, err := tokenstore.Get(wantService, handle)
71		if err != nil {
72			t.Fatalf("get token: %v", err)
73		}
74		gotToken, expiresAt := tokenstore.DecodeTokenWithExpiration(encoded)
75		if gotToken != token {
76			t.Fatalf("stored token mismatch")
77		}
78		if !expiresAt.After(time.Now()) {
79			t.Fatalf("stored expiry %s is not in the future", expiresAt)
80		}
81	}
