83	func TestMigrateLegacyLoginContext_SynthesizesContext(t *testing.T) {
84		// Mocks the legacy keyring + swaps the new tokenstore + sets the config
85		// dir — all process-global, so not parallel.
86		keyring.MockInit()
87		cfgDir := t.TempDir()
88		t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
89		restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
