95		legacy := makeJWT(t, fmt.Sprintf(`{"iss":%q,"handle":%q,"exp":%d}`, coreURL, handle, exp))
96	
97		// Seed only the legacy single-host keyring entry.
98		if err := NewStore().SaveToken(api.AuthBaseURL(), legacy); err != nil {
99			t.Fatalf("seed legacy token: %v", err)
100		}
101	
102		migrated, err := MigrateLegacyLoginContext()
103		if err != nil {
104			t.Fatalf("MigrateLegacyLoginContext: %v", err)
105		}
106		if !migrated {
107			t.Fatal("expected migration to synthesize a context")
108		}
109	
110		f, err := contexts.Load(cfgDir)
111		if err != nil {
112			t.Fatalf("load contexts: %v", err)
113		}
114		if got := f.ContextsForIssuer(coreURL); len(got) != 1 {
115			t.Fatalf("contexts for issuer = %d, want 1", len(got))
116		}
