118		// Idempotent: a second call is a no-op now that a context exists.
119		migratedAgain, err := MigrateLegacyLoginContext()
120		if err != nil {
121			t.Fatalf("second MigrateLegacyLoginContext: %v", err)
122		}
123		if migratedAgain {
124			t.Fatal("second migration should be a no-op")
125		}
126	}
