145		}
146		if got != "the-jwt" {
147			t.Fatalf("token = %q, want the-jwt", got)
148		}
149	
150		if _, err := LoginTokenForContext(nil); err == nil {
151			t.Fatal("expected error for nil context")
152		}
153	}
