155	func TestContextStore_PrefersCurrentContextThenLegacy(t *testing.T) {
156		keyring.MockInit()
157		cfgDir := t.TempDir()
158		t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
159		restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
160		t.Cleanup(restore)
161	
162		store := NewContextStore()
163	
164		// No context yet: falls back to the legacy entry.
165		if err := store.SaveToken(api.AuthBaseURL(), "legacy-token"); err != nil {
166			t.Fatalf("seed legacy: %v", err)
167		}
168		legacyGot, err := store.GetToken(api.AuthBaseURL())
169		if err != nil {
170			t.Fatalf("GetToken (legacy): %v", err)
171		}
172		if legacyGot != "legacy-token" {
173			t.Fatalf("with no context, GetToken = %q, want legacy-token", legacyGot)
174		}
