176		// Record a context: its token now wins over the legacy entry.
177		exp := time.Now().Add(time.Hour).Unix()
178		ctxToken := makeJWT(t, fmt.Sprintf(`{"iss":"https://core.example.com","handle":"alice","exp":%d}`, exp))
179		if _, err := RecordLoginContext(ctxToken); err != nil {
180			t.Fatalf("RecordLoginContext: %v", err)
181		}
182		got, err := store.GetToken(api.AuthBaseURL())
183		if err != nil {
184			t.Fatalf("GetToken: %v", err)
185		}
186		if got != ctxToken {
187			t.Fatal("with a current context, GetToken should return the context token")
188		}
