191	func TestRemoveCurrentContext(t *testing.T) {
192		cfgDir := t.TempDir()
193		t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
194		restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
