219	func TestSetCurrentContext(t *testing.T) {
220		cfgDir := t.TempDir()
221		t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
222		restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
223		t.Cleanup(restore)
