225		// Two contexts from two cores; the second becomes current on login.
226		exp := time.Now().Add(time.Hour).Unix()
227		if _, err := RecordLoginContext(makeJWT(t, fmt.Sprintf(`{"iss":"https://a.example.com","handle":"alice","exp":%d}`, exp))); err != nil {
228			t.Fatalf("record a: %v", err)
229		}
230		if _, err := RecordLoginContext(makeJWT(t, fmt.Sprintf(`{"iss":"https://b.example.com","handle":"alice","exp":%d}`, exp))); err != nil {
231			t.Fatalf("record b: %v", err)
232		}
233	
234		all, current, err := Contexts()
235		if err != nil {
236			t.Fatalf("Contexts: %v", err)
237		}
238		if len(all) != 2 {
239			t.Fatalf("got %d contexts, want 2", len(all))
240		}
241		if current != "b.example.com" {
242			t.Fatalf("current = %q, want b.example.com (most recent login)", current)
243		}
244	
245		// Switch back to the first.
246		if err := SetCurrentContext("a.example.com"); err != nil {
247			t.Fatalf("SetCurrentContext: %v", err)
248		}
249		_, current, err = Contexts()
250		if err != nil {
251			t.Fatalf("Contexts after switch: %v", err)
252		}
253		if current != "a.example.com" {
254			t.Fatalf("after switch, current = %q, want a.example.com", current)
255		}
256	
257		// Unknown context errors.
258		if err := SetCurrentContext("nope"); err == nil {
259			t.Fatal("expected error switching to unknown context")
260		}
261	}
