1	package discovery
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"time"
11	
12		"github.com/gofrs/flock"
13	)
14	
15	const (
16		cacheFileName = "nodes.json"
17		lockTimeout   = 5 * time.Second
18		lockRetry     = 100 * time.Millisecond
19	
20		// DefaultTTL is the cache TTL for replica sets discovered via info/refs.
21		DefaultTTL = 24 * time.Hour
22	)
23	
24	// ClusterCache is the top-level cache structure, keyed by cluster host.
25	type ClusterCache map[string]*ClusterEntry
26	
27	// ClusterEntry holds cached data for a single cluster.
28	type ClusterEntry struct {
29		Nodes          []string              `json:"nodes"`
30		NodesExpiresAt time.Time             `json:"nodes_expires_at"`
31		Repos          map[string]*RepoEntry `json:"repos,omitempty"`
32	}
33	
34	// RepoEntry caches the hosting nodes for a single repository.
35	type RepoEntry struct {
36		Nodes     []string  `json:"nodes"`
37		ExpiresAt time.Time `json:"expires_at"`
38	}
39	
40	// DefaultCacheDir returns ~/.cache/entire, respecting XDG_CACHE_HOME.
41	func DefaultCacheDir() string {
42		if xdg := os.Getenv("XDG_CACHE_HOME"); xdg != "" {
43			return filepath.Join(xdg, "entire")
44		}
45		home, _ := os.UserHomeDir() //nolint:errcheck // best-effort default
46		return filepath.Join(home, ".cache", "entire")
47	}
48	
49	// LoadCache reads the node cache from disk. Returns an empty cache if the file
50	// does not exist.
51	func LoadCache(cacheDir string) (ClusterCache, error) {
52		path := filepath.Join(cacheDir, cacheFileName)
53	
54		data, err := os.ReadFile(path) // #nosec G304
55		if err != nil {
56			if os.IsNotExist(err) {
57				return make(ClusterCache), nil
58			}
59			return nil, fmt.Errorf("read cache: %w", err)
60		}
61	
62		var cache ClusterCache
63		if err := json.Unmarshal(data, &cache); err != nil {
64			// Corrupted cache — start fresh.
65			return make(ClusterCache), nil //nolint:nilerr // intentional: treat corrupt cache as empty
66		}
67		return cache, nil
68	}
69	
70	// SaveCache writes the cache to disk atomically.
71	func SaveCache(cacheDir string, cache ClusterCache) error {
72		if err := os.MkdirAll(cacheDir, 0700); err != nil {
73			return fmt.Errorf("create cache dir: %w", err)
74		}
75	
76		path := filepath.Join(cacheDir, cacheFileName)
77	
78		fl := flock.New(path + ".lock")
79		ctx, cancel := context.WithTimeout(context.Background(), lockTimeout)
80		defer cancel()
81	
82		locked, err := fl.TryLockContext(ctx, lockRetry)
83		if err != nil {
84			return fmt.Errorf("acquire cache lock: %w", err)
85		}
86		if !locked {
87			return errors.New("timeout acquiring cache lock")
88		}
89		defer fl.Unlock() //nolint:errcheck // unlock failure is non-fatal
90	
91		data, err := json.MarshalIndent(cache, "", "  ")
92		if err != nil {
93			return fmt.Errorf("marshal cache: %w", err)
94		}
95	
96		tmp := path + ".tmp"
97		if err := os.WriteFile(tmp, data, 0600); err != nil {
98			return fmt.Errorf("write cache tmp: %w", err)
99		}
100		if err := os.Rename(tmp, path); err != nil {
101			os.Remove(tmp) //nolint:gosec // cleanup best-effort
102			return fmt.Errorf("rename cache: %w", err)
103		}
104		return nil
105	}
106	
107	// GetClusterNodes returns the cached cluster nodes. The second return value
108	// indicates whether the cache entry is fresh (not expired).
109	func (c ClusterCache) GetClusterNodes(cluster string) ([]string, bool) {
110		entry := c[cluster]
111		if entry == nil || len(entry.Nodes) == 0 {
112			return nil, false
113		}
114		return entry.Nodes, time.Now().Before(entry.NodesExpiresAt)
115	}
116	
117	// SetClusterNodes stores cluster nodes with the given TTL.
