package test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"entire.io/test/testserver"
	"entire.io/test/testutils"
	"github.com/stretchr/testify/require"
)

// TestGitRemoteEntire_ShallowDepth1Clone is the real-git smoke test
// for v0/v1 shallow fetch through git-remote-entire. The synthetic
// suite in internal/remotehelper/githelper/shallow_v1_e2e_test.go
// pins the bridge's POST-shape and stdout wire-shape; this one runs
// the actual `git` binary against a real entire-server, so it catches
// anything the synthetic stateful-client harness doesn't faithfully
// reproduce (capability ordering, agent string, multi-ack flavour,
// PACK demuxing).
//
// Seed: three commits A→B→C on the server. Clone with --depth 1.
// Assert:
//   - clone succeeds (the original bug was a hard hang here),
//   - the working tree is marked shallow (`.git/shallow` exists),
//   - history is bounded to a single commit (rev-list --count == 1),
//   - that single commit's content matches commit C.
func TestGitRemoteEntire_ShallowDepth1Clone(t *testing.T) {
	t.Parallel()
	env := testserver.SetupTestEnv(t, 1)

	env.SignupAndLogin("alice", "password")
	env.ProvisionRepo("alice", "shallow-repo")

	// Initial clone + three commits so depth=1 has something to bound.
	repoURL := "entire://" + env.Host + "/et/alice/shallow-repo"
	testutils.RunGit(t, []string{"clone", repoURL}, env.GitOpts(env.WorkDir)...)
	repoDir := filepath.Join(env.WorkDir, "shallow-repo")

	for _, commit := range []struct{ file, msg string }{
		{"a.txt", "a"},
		{"b.txt", "b"},
		{"c.txt", "c"},
	} {
		require.NoError(t,
			os.WriteFile(filepath.Join(repoDir, commit.file), []byte(commit.msg+"\n"), 0o644))
		testutils.RunGit(t, []string{"add", commit.file}, testutils.WithCwd(repoDir))
		testutils.RunGit(t, []string{"commit", "-m", commit.msg}, testutils.WithCwd(repoDir))
	}
	testutils.RunGit(t, []string{"push"}, env.GitOpts(repoDir)...)

	// Capture the tip SHA so we can assert the shallow clone landed
	// exactly on commit `c` (not on some interior commit that the
	// boundary walk picked by mistake).
